    (r"^(.+?)ling$", "lng"),
    (r"^(.+?)ting$", "tng"),
    (r"^(.+?)ning$", "nng"),
    (r"^(.+?)ring$", "rng"),
    (r"^(.+?)sing$", "sng"),
    (r"^(.+?)ing$", "ng"),
    (r"^(.+?)ily$", "ly"),
